export { LinkPreview } from "./link-preview";
export { parseSerializableLinkPreview } from "./schema";
export type { SerializableLinkPreview } from "./schema";

"use client";

import { FC } from "react";
import { cn } from "@/lib/utils";
import { ExternalLink } from "lucide-react";
import { ActionButtons } from "@/components/tool-ui/shared/action-buttons";
import { RATIO_CLASS_MAP, getFitClass } from "@/components/tool-ui/shared/media";
import type { SerializableLinkPreview } from "./schema";

interface LinkPreviewProps extends SerializableLinkPreview {
  className?: string;
  onResponseAction?: (actionId: string) => void;
}

export const LinkPreview: FC<LinkPreviewProps> = ({
  id,
  href,
  title,
  description,
  image,
  domain,
  favicon,
  ratio = "16:9",
  createdAt,
  responseActions,
  className,
  onResponseAction,
}) => {
  return (
    <div
      className={cn("flex flex-col gap-3", className)}
      data-tool-ui-id={id}
      data-slot="link-preview"
    >
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        className="bg-card text-card-foreground border shadow-none group block rounded-xl overflow-hidden hover:shadow-none transition-all"
      >
        {/* Preview Image */}
        {image && (
          <div className={cn("relative overflow-hidden bg-muted", RATIO_CLASS_MAP[ratio])}>
            <img
              src={image}
              alt={title || "Link preview"}
              className={cn("w-full h-full object-cover transition-transform duration-300 group-hover:scale-105", getFitClass("cover"))}
              loading="lazy"
            />
          </div>
        )}

        {/* Content */}
        <div className="p-4 space-y-2">
          {/* Domain with favicon */}
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            {favicon && (
              <img src={favicon} alt="" className="w-4 h-4 rounded" />
            )}
            <span>{domain || new URL(href).hostname}</span>
            <ExternalLink className="w-3 h-3 ml-auto opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>

          {/* Title */}
          {title && (
            <h3 className="font-semibold text-base leading-snug line-clamp-2 group-hover:text-primary transition-colors">
              {title}
            </h3>
          )}

          {/* Description */}
          {description && (
            <p className="text-sm text-muted-foreground line-clamp-2">
              {description}
            </p>
          )}

          {/* Created At */}
          {createdAt && (
            <time className="text-xs text-muted-foreground block">
              {new Date(createdAt).toLocaleDateString(undefined, {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
              })}
            </time>
          )}
        </div>
      </a>

      {/* Response Actions */}
      {responseActions && responseActions.length > 0 && (
        <ActionButtons
          actions={responseActions}
          onAction={onResponseAction}
        />
      )}
    </div>
  );
};

import type { Action } from "../shared/schema";

export interface SerializableLinkPreview {
  id: string;
  href: string;
  title?: string;
  description?: string;
  image?: string;
  domain?: string;
  favicon?: string;
  ratio?: "auto" | "1:1" | "4:3" | "16:9" | "9:16";
  createdAt?: string;
  responseActions?: Action[];
}

export function parseSerializableLinkPreview(data: any): SerializableLinkPreview {
  return {
    id: data.id || crypto.randomUUID(),
    href: data.href || "",
    title: data.title,
    description: data.description,
    image: data.image,
    domain: data.domain,
    favicon: data.favicon,
    ratio: data.ratio || "16:9",
    createdAt: data.createdAt,
    responseActions: data.responseActions,
  };
}

"use client";

import { FC } from "react";
import { Button } from "@/components/ui/button";
import type { Action } from "./schema";

interface ActionButtonsProps {
  actions?: Action[];
  onAction?: (actionId: string) => void;
  className?: string;
}

export const ActionButtons: FC<ActionButtonsProps> = ({
  actions,
  onAction,
  className,
}) => {
  if (!actions || actions.length === 0) return null;

  return (
    <div className={`flex flex-wrap gap-2 ${className || ""}`}>
      {actions.map((action) => (
        <Button
          key={action.id}
          variant={action.variant || "outline"}
          size="sm"
          disabled={action.disabled}
          onClick={() => onAction?.(action.id)}
          className="text-xs"
        >
          {action.label}
        </Button>
      ))}
    </div>
  );
};

export const RATIO_CLASS_MAP = {
  auto: "aspect-auto",
  "1:1": "aspect-square",
  "4:3": "aspect-[4/3]",
  "16:9": "aspect-video",
  "9:16": "aspect-[9/16]",
} as const;

export function getFitClass(fit: "cover" | "contain" = "cover") {
  return fit === "cover" ? "object-cover" : "object-contain";
}

export const OVERLAY_GRADIENT =
  "bg-gradient-to-t from-black/60 via-black/20 to-transparent";

export function sanitizeHref(href: string | undefined): string | undefined {
  if (!href) return undefined;
  try {
    const url = new URL(href);
    if (url.protocol === "javascript:") return undefined;
    return href;
  } catch {
    return undefined;
  }
}

/**
 * Shared types for social post components
 */

export interface Action {
  id: string;
  label: string;
  prompt?: string; // The message to send when clicked
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
  disabled?: boolean;
}

export interface BaseAuthor {
  name: string;
  avatarUrl: string;
}

export interface MediaItem {
  type: "image" | "video";
  url: string;
  alt?: string;
  aspectRatio?: number;
}

export interface LinkPreview {
  url: string;
  title?: string;
  description?: string;
  imageUrl?: string;
  domain?: string;
}

export interface BaseStats {
  likes?: number;
  shares?: number;
  comments?: number;
}
